src='''from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    exterior = set()
    queue = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == background and (r, c) not in exterior:
                exterior.add((r, c))
                queue.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == background and (r, c) not in exterior:
                exterior.add((r, c))
                queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == background
                    and (nr, nc) not in exterior):
                exterior.add((nr, nc))
                queue.append((nr, nc))

    return [[4 if value == background and (r, c) not in exterior else value
             for c, value in enumerate(row)]
            for r, row in enumerate(grid)]
'''
