def flood_transform(grid, diagonal=False):
    h,w=len(grid),len(grid[0]); bg=max({v for row in grid for v in row},key=lambda v:sum(row.count(v) for row in grid))
    steps=[(-1,0),(1,0),(0,-1),(0,1)]
    if diagonal: steps += [(-1,-1),(-1,1),(1,-1),(1,1)]
    ext=set(); q=deque()
    for r in range(h):
        for c in range(w):
            if (r in (0,h-1) or c in (0,w-1)) and grid[r][c]==bg and (r,c) not in ext: ext.add((r,c));q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in steps:
            rr,cc=r+dr,c+dc
            if 0<=rr<h and 0<=cc<w and grid[rr][cc]==bg and (rr,cc) not in ext: ext.add((rr,cc));q.append((rr,cc))
    return [[4 if v==bg and (r,c) not in ext else v for c,v in enumerate(row)] for r,row in enumerate(grid)]
